SELECT COUNT(*)
FROM `reservation`
WHERE resource_id = #{resourceId}
  AND status IN ('CONFIRMED', 'IN_USE')
  AND start_time < #{endTime}
  AND end_time > #{startTime}

SELECT rv.id, rv.user_id, rv.resource_id, rv.reserve_date, rv.start_time, rv.end_time,
       rv.status, rv.checkin_time, rv.finish_time, rv.cancel_reason, rv.remark,
       rv.create_time, rv.update_time,
       r.name AS resource_name
FROM `reservation` rv
LEFT JOIN `resource` r ON rv.resource_id = r.id

    rv.user_id = #{userId}

        AND rv.status = #{status}


ORDER BY rv.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM `reservation`

    user_id = #{userId}

        AND status = #{status}

SELECT rv.id, rv.user_id, rv.resource_id, rv.reserve_date, rv.start_time, rv.end_time,
       rv.status, rv.checkin_time, rv.finish_time, rv.cancel_reason, rv.remark,
       rv.create_time, rv.update_time,
       r.name AS resource_name,
       u.username AS username
FROM `reservation` rv
LEFT JOIN `resource` r ON rv.resource_id = r.id
LEFT JOIN `user` u ON rv.user_id = u.id

    AND rv.user_id = #{userId}
    AND rv.resource_id = #{resourceId}
    AND rv.status = #{status}

ORDER BY rv.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM `reservation` rv

    AND rv.user_id = #{userId}
    AND rv.resource_id = #{resourceId}
    AND rv.status = #{status}

